const rows = $json.results || [];

let context = {};
try {
  context = $("Build Risk Query").first().json;
} catch (e) {
  context = {};
}

const riskItems = rows.map((row) => ({
  item_id: row.item_id || null,
  item_type: row.item_type || null,
  item_name: row.item_name || null,
  properties: row.properties || {},
  relationship: row.relationship || null,
  connected_labels: row.connected_labels || [],
  connected_entity: row.connected_entity || null,
}));

return [
  {
    json: {
      agent: "risk_analyst",
      domain: "Risk Analyst",
      status: "data_retrieved",
      question: context.question || "",
      evidenceLabel: "riskItems",
      evidenceData: riskItems,
      generatedCypher: context.query || "",
      rawResult: $json,
    },
  },
];

const agent = $json.agent || "risk_analyst";
const domain = $json.domain || "Risk Analyst";
const question = $json.question || "";
const evidenceLabel = $json.evidenceLabel || "riskItems";
const evidenceData = $json.evidenceData || [];
const rawResult = $json.rawResult || {};
const generatedCypher = $json.generatedCypher || "";
const dbSchema = rawResult.schema || "";

let sourceChunks = [];
try {
  sourceChunks = $("When Executed by Another Workflow").first().json.sourceChunks || [];
} catch (e) {}

const contextStr = sourceChunks.length > 0
  ? "\n\nRetrieved Unstructured Document Context:\n" + sourceChunks.map(c => "--- File: " + (c.documentName || c.filename) + " ---\n" + c.text).join("\n\n")
  : "";

const systemPrompt = `
You are a Risk Analyst Agent for a supply chain knowledge graph.

Active Database Schema:
${dbSchema || "No active schema available."}

Rules:
- Answer risk, incident, audit, maintenance, and test-report questions.
- Use the provided graph query results and any retrieved unstructured document context.
- Do not invent missing records or facts.
- Identify risk patterns, affected entities, and possible bottlenecks.
- Explain the business impact clearly.
- Give practical mitigation recommendations.
- If the graph/RAG data is limited, clearly say that.

Strict actor interpretation rules:
- Not every Actor node is a supplier.
- Only call an actor a supplier if actor_role is "supplier", actor_role is "manufacturer", or the relationship evidence shows SUPPLIES.
- Actors with actor_origin = "llm_extracted_actor" should be described as extracted actors, service providers, facilities, technicians, or vendors depending on evidence.
- Do not call Recycling Facility P or Waste Disposal Provider Q suppliers unless the graph evidence explicitly says they supply something.
- Preserve exact names from the graph.

Return ONLY valid JSON.
`;

const userPrompt = `
User question:
${question}

Risk evidence:
${JSON.stringify(evidenceData, null, 2)}

Raw graph result:
${JSON.stringify(rawResult, null, 2)}${contextStr}

Return JSON with this exact schema:
{
  "answer": "string",
  "keyFindings": ["string"],
  "riskInsights": [
    {
      "id": "string",
      "type": "string",
      "name": "string",
      "riskLevel": "low | medium | high | unknown",
      "insight": "string"
    }
  ],
  "affectedEntities": [
    {
      "entity": "string",
      "relationship": "string",
      "impact": "string"
    }
  ],
  "recommendations": ["string"],
  "confidence": "low | medium | high"
}
`;

return [
  {
    json: {
      agent,
      domain,
      question,
      evidenceLabel,
      evidenceData,
      generatedCypher,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: systemPrompt,
          },
          {
            role: "user",
            content: userPrompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2048,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The risk analyst could not generate a summary.",
    keyFindings: [],
    riskInsights: [],
    affectedEntities: [],
    recommendations: [],
    confidence: "low",
  };
}

let context = {};
try {
  context = $("Build LLM Summary Payload").first().json;
} catch (e) {
  context = {};
}

return [
  {
    json: {
      agent: "risk_analyst",
      domain: "Risk Analyst",
      status: "completed",
      question: context.question || "",
      answer: parsed.answer || "",
      keyFindings: parsed.keyFindings || [],
      riskInsights: parsed.riskInsights || [],
      affectedEntities: parsed.affectedEntities || [],
      recommendations: parsed.recommendations || [],
      confidence: parsed.confidence || "medium",
      evidence: {
        riskItems: context.evidenceData || [],
      },
      generatedCypher: context.generatedCypher || "",
      rawLlmOutput: parsed,
    },
  },
];

const selectedAgents = $json.selectedAgents || [];

const shouldRun =
  selectedAgents.includes("risk_analyst") ||
  selectedAgents.includes("all");

return [
  {
    json: {
      ...$json,
      shouldRun,
    },
  },
];

return [
  {
    json: {
      agent: "risk_analyst",
      domain: "Risk Analyst",
      status: "skipped",
      question: $json.question || "",
      answer: "",
      keyFindings: [],
      recommendations: [],
      confidence: "not_applicable",
      evidence: {},
    },
  },
];
